command:
if (args[0] === "on") {

const lastArg = args[args.length - 1];
const triggeringActor = game.actors.get(lastArg?.actorId);
  const triggeringUser = [... game.users].filter(u => u.character?.id === triggeringActor.id)[0];
// Cible(s) du joueur déclencheur (et pas du GM)
const targets = triggeringUser ? Array.from(triggeringUser.targets) : [];
const target = targets[0];

if (!target) {
  ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgNoTarget"));
  return;
}

// Infos de grille
const gridSize = canvas.grid.size;

// Coordonnées de la case de base du lanceur (celui qui tire la chaîne)
const srcX = token.position.x;
const srcY = token.position.y;

// Cases adjacentes au lanceur (haut, bas, gauche, droite)
const adjacents = [
  { x: srcX,            y: srcY - gridSize }, // haut
  { x: srcX,            y: srcY + gridSize }, // bas
  { x: srcX - gridSize, y: srcY },            // gauche
  { x: srcX + gridSize, y: srcY }             // droite
];

// Position de la cible agrippée
const start = target.center;

// Cherche la case adjacente la plus proche de la cible
let best = null;
let bestD2 = Infinity;
for (let pos of adjacents) {
  const d2 = (pos.x - start.x) ** 2 + (pos.y - start.y) ** 2;
  if (d2 < bestD2) { bestD2 = d2; best = pos; }
}

// Si pas trouvé
if (!best) {
  ui.notifications.error(game.i18n.localize("FQCARDENGINE.MacroErrorMsgNoFreeAdjacentCell"));
  return;
}

// Séquence d'agrippement : la chaîne part du lanceur, la cible est ramenée
new Sequence()
  .effect()
    .file("jb2a.chain_lightning.secondary.blue")
    .atLocation(token)
    .stretchTo(target)
    .elevation(0)
  .wait(200)
  .effect()
    .copySprite(target)
    .fadeIn(50)
    .duration(300)
    .fadeOut(150)
    .filter("Blur")
    .elevation(0)
  .animation()
    .on(target)
    .teleportTo(best)
    .snapToGrid()
    .waitUntilFinished()
  .effect()
    .file("jb2a.smoke.puff.centered.grey")
    .atLocation(best)
    .scaleToObject()
  .play();
}
